import pandas as pd, json
train = pd.read_parquet('taco_verl/train.parquet')

# Check for empty or degenerate ground truths
issues = []
for i, row in train.iterrows():
    gt = json.loads(row['reward_model']['ground_truth'])
    inputs = gt.get('inputs', [])
    outputs = gt.get('outputs', [])
    n = len(inputs)
    if n == 0:
        issues.append((i, row['extra_info'].get('problem_id'), 'empty_inputs'))
    if n == 1:
        issues.append((i, row['extra_info'].get('problem_id'), 'single_test'))
    # check some inputs are dict-like or strings
    for j, inp in enumerate(inputs):
        if not isinstance(inp, (str, list)):
            issues.append((i, row['extra_info'].get('problem_id'), f'inp_type_{j}_{type(inp).__name__}'))
    for j, out in enumerate(outputs):
        if not isinstance(out, (str, list)):
            issues.append((i, row['extra_info'].get('problem_id'), f'out_type_{j}_{type(out).__name__}'))

print('Issue count:', len(issues))
for x in issues[:80]:
    print(x)
