import pandas as pd, json, re

train = pd.read_parquet('taco_verl/train.parquet')

# Comprehensive corruption scan per row
report = []
for idx, r in train.iterrows():
    pid = r['extra_info']['problem_id'] if isinstance(r['extra_info'], dict) else None
    gt = json.loads(r['reward_model']['ground_truth'])
    inputs = gt.get('inputs', [])
    outputs = gt.get('outputs', [])
    n = len(outputs)
    # a) empty outputs
    empty_out = [i for i,o in enumerate(outputs) if isinstance(o,str) and o.strip()=='']
    empty_in  = [i for i,x in enumerate(inputs) if isinstance(x,str) and x.strip()=='']
    # c) duplicate input -> inconsistent output
    seen = {}
    dup_inconsist = []
    for i,(inp,out) in enumerate(zip(inputs, outputs)):
        key = inp if isinstance(inp,str) else json.dumps(inp)
        if key in seen:
            seen[key].append(i)
        else:
            seen[key] = [i]
    for key, idxs in seen.items():
        if len(idxs) > 1:
            outs = {json.dumps(outputs[i]) for i in idxs}
            if len(outs) > 1:
                dup_inconsist.append((key, idxs))
    if empty_out or empty_in or dup_inconsist:
        report.append((pid, n, empty_in, empty_out, len(dup_inconsist), dup_inconsist[:2]))

print('Rows with empty-in/out or duplicate-inconsistent:', len(report))
for line in report:
    print(line)
