    t = re.sub(r'\\[a-zA-Z]+', ' ', t)       # strip latex commands
    t = re.sub(r'[^a-z0-9]+', ' ', t.lower())
    return re.sub(r'\s+', ' ', t).strip()

def extract_question(prompt):
    if isinstance(prompt, (list, tuple)) and len(prompt) and isinstance(prompt[0], dict):
        s = prompt[0].get('content', '')
    else:
        s = str(prompt)
    if 'QUESTION:' in s:
        s = s.split('QUESTION:', 1)[1]
    if '\nANSWER:' in s:
        s = s.split('\nANSWER:', 1)[0]
