import json, sys
sys.set_int_max_str_digits(0)

f = open('/autorlbench/datasets/likaixin__TACO-verified/taco_verified.json', 'r')
data = json.load(f)
f.close()
print(f'Top-level type: {type(data).__name__}, len={len(data)}')

# If it's a list of dicts
def show(d, prefix='', depth=0, maxdepth=2):
    if depth > maxdepth: return
    if isinstance(d, dict):
        for k in list(d.keys())[:8]:
            v = d[k]
            if isinstance(v, (dict, list)):
                print(f'{prefix}{k}: {type(v).__name__} len={len(v)}')
                if depth < maxdepth-1:
                    show(v, prefix+'  ', depth+1, maxdepth)
            else:
                print(f'{prefix}{k}: {str(v)[:90]}')
    elif isinstance(d, list):
        print(f'{prefix}[list] len={len(d)}')
        if d:
            show(d[0], prefix+'  ', depth+1, maxdepth)

show(data, '', 0, 2)
PYEOF
